int main() {
    ifstream fin("file.txt");
    vector<string> buf;
    string line, w;
    while (getline(fin, line)) {
        istringstream iss(line);
        int i = 0;
        while (iss >> w) {
            if ((int)buf.size() <= i) buf.push_back("");
            if (!buf[i].empty()) buf[i] += ' ';
            buf[i] += w;
            ++i;
        }
    }
    for (auto &col : buf) cout << col << "\n";
}

