import java.util.*;
import java.io.*;
class Solution {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new FileReader("file.txt"));
        List<List<String>> buf = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            String[] parts = line.trim().split("\\s+");
            if (parts.length == 1 && parts[0].isEmpty()) continue;
            while (buf.size() < parts.length) buf.add(new ArrayList<>());
            for (int i = 0; i < parts.length; i++) buf.get(i).add(parts[i]);
        }
        StringBuilder sb = new StringBuilder();
        for (List<String> col : buf) sb.append(String.join(" ", col)).append('\n');
        System.out.print(sb);
    }
}

